package com.example.lab4.service; import com.example.lab4.domain.*; import com.example.lab4.dto.*; import com.example.lab4.repo.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID; @Service public class SupportRequestService { private final SupportRequestRepository requests; private final CustomerRepository customers; public SupportRequestService(SupportRequestRepository r,CustomerRepository c){requests=r;customers=c;} @Transactional public SupportRequestView close(UUID id){SupportRequest r=requests.findById(id).orElseThrow(); if(!r.getPriority().equals("HIGH")){r.setStatus("CLOSED");} return new SupportRequestView(r.getId(),r.getPriority(),r.getStatus());} }
